import hashlib, json
def digest(rec):
    canon = json.dumps(rec, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canon.encode()).hexdigest()
store = {}
for rec in [{"id": "r1", "v": 10}, {"id": "r2", "v": 20}]:
    store[digest(rec)] = rec
probe = {"v": 10, "id": "r1"}
print("found:", store.get(digest(probe)))
print("digest prefix:", digest(probe)[:16])

