import unicodedata, re
def normalize(s):
    s = unicodedata.normalize("NFKC", s)
    s = re.sub(r"[\W_]+", "", s.casefold())
    return s
keys = {"JAH-SPEC-000123": "spec record", "jah_spec_000123": "alias row"}
table = {normalize(k): v for k, v in keys.items()}
for probe in ["jah-spec-000123", "JAH SPEC 000123", "jah_spec_000123"]:
    print(repr(probe), "->", table.get(normalize(probe), "MISS"))

