import hashlib
def shingles(s, n=3):
    s = s.lower().split(); return [" ".join(s[i:i+n]) for i in range(len(s)-n+1)]
def simhash(text):
    bits = [0]*32
    for sh in shingles(text):
        h = int(hashlib.md5(sh.encode()).hexdigest(), 16)
        for i in range(32):
            bits[i] += 1 if (h >> i) & 1 else -1
    return sum(1 << i for i, b in enumerate(bits) if b > 0)
def ham(a, b): return bin(a ^ b).count("1")
f1 = simhash("the archive holds deep search records")
f2 = simhash("the archive holds deep search entries")
f3 = simhash("quantum baking recipes for beginners")
print("near-dupe distance:", ham(f1, f2), "| unrelated distance:", ham(f1, f3))

